:root {
  --fond: #ffffff;
  --texte: #1a1a1a;
  --accent: #0a7d33;
  --bordure: #e2e2e2;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fond: #121212;
    --texte: #f1f1f1;
    --accent: #4ade80;
    --bordure: #333;
  }
}

body {
  background: var(--fond);
  color: var(--texte);
  font-family: system-ui, sans-serif;
