const carrousel = document.querySelector(".carrousel");
const slides = carrousel.querySelectorAll("figure");
let courant = 0;

function montrerSlide(index) {
  courant = (index + slides.length) % slides.length;
  slides.forEach((slide, i) => {
    slide.hidden = i !== courant;
  });
  carrousel.querySelector(".annonce").textContent =
    `Slide ${courant + 1} sur ${slides.length}`;
}

carrousel.querySelector(".precedent").addEventListener("click", () => montrerSlide(courant - 1));
carrousel.querySelector(".suivant").addEventListener("click", () => montrerSlide(courant + 1));

carrousel.addEventListener("keydown", (event) => {
  if (event.key === "ArrowLeft") montrerSlide(courant - 1);
  if (event.key === "ArrowRight") montrerSlide(courant + 1);
});

montrerSlide(0);

const compteurs = document.querySelectorAll(".stat-valeur");

const observateur = new IntersectionObserver(
  (entrees) => {
    entrees.forEach((entree) => {
      if (!entree.isIntersecting) return;
      const element = entree.target;
      const cible = Number(element.dataset.cible);
      const duree = 1200;
      const debut = performance.now();

      function pas(maintenant) {
        const progression = Math.min((maintenant - debut) / duree, 1);
        element.textContent = Math.round(cible * progression).toLocaleString("fr-FR");
        if (progression < 1) requestAnimationFrame(pas);
      }

      requestAnimationFrame(pas);
      observateur.unobserve(element);
    });
  },
  { threshold: 0.5 }
);

compteurs.forEach((compteur) => observateur.observe(compteur));

function debounce(fonction, delai) {
  let minuteur;
  return (...args) => {
    clearTimeout(minuteur);
    minuteur = setTimeout(() => fonction(...args), delai);
  };
}

