const onglets = document.querySelectorAll('[role="tab"]');
const panneaux = document.querySelectorAll('[role="tabpanel"]');

function activerOnglet(onglet) {
  onglets.forEach((t) => {
    const actif = t === onglet;
    t.setAttribute("aria-selected", String(actif));
    t.tabIndex = actif ? 0 : -1;
  });
  panneaux.forEach((panneau) => {
    panneau.hidden = panneau.id !== onglet.getAttribute("aria-controls");
  });
  onglet.focus();
}

onglets.forEach((onglet) => {
  onglet.addEventListener("click", () => activerOnglet(onglet));
  onglet.addEventListener("keydown", (event) => {
    const index = [...onglets].indexOf(onglet);
    if (event.key === "ArrowRight") activerOnglet(onglets[(index + 1) % onglets.length]);
    if (event.key === "ArrowLeft") activerOnglet(onglets[(index - 1 + onglets.length) % onglets.length]);
  });
});

const bouton = document.querySelector("#copier-lien");
const libelleInitial = bouton.textContent;
let minuteur;

bouton.addEventListener("click", async () => {
