import { useState } from "react";

export function FormulaireInscription() {
  const [champs, setChamps] = useState({ nom: "", email: "", motdepasse: "" });
  const [erreurs, setErreurs] = useState({});
  const [enCours, setEnCours] = useState(false);

  const changer = (event) => {
    const { name, value } = event.target;
    setChamps((c) => ({ ...c, [name]: value }));
  };

  async function soumettre(event) {
    event.preventDefault();
    const nouvellesErreurs = {};
    if (champs.nom.trim().length < 2) nouvellesErreurs.nom = "Nom trop court.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(champs.email))
      nouvellesErreurs.email = "Email invalide.";
    if (champs.motdepasse.length < 8)
      nouvellesErreurs.motdepasse = "8 caractères minimum.";
    setErreurs(nouvellesErreurs);
    if (Object.keys(nouvellesErreurs).length > 0) return;

    setEnCours(true);
    try {
      const reponse = await fetch("/api/inscription", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(champs),
      });
      if (!reponse.ok) throw new Error("inscription");
      alert("Bienvenue " + champs.nom + " !");
    } catch {
      setErreurs({ global: "Inscription impossible pour le moment." });
    } finally {
      setEnCours(false);
    }
  }

  return (
    <form onSubmit={soumettre} noValidate>
      {["nom", "email", "motdepasse"].map((nom) => (
        <div key={nom}>
          <label htmlFor={nom}>{nom}</label>
          <input
            id={nom}
            name={nom}
            type={nom === "motdepasse" ? "password" : nom === "email" ? "email" : "text"}
            value={champs[nom]}
            onChange={changer}
          />
          {erreurs[nom] && <p className="erreur">{erreurs[nom]}</p>}
        </div>
      ))}
      {erreurs.global && <p role="alert">{erreurs.global}</p>}
      <button type="submit" disabled={enCours}>
        {enCours ? "Inscription..." : "S'inscrire"}
      </button>
    </form>
  );
}

import { useCallback, useEffect, useState } from "react";

interface EtatFetch<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
}

export function useFetch<T>(url: string): EtatFetch<T> & { refetch: () => void } {
  const [etat, setEtat] = useState<EtatFetch<T>>({
    data: null,
    loading: true,
    error: null,
  });
  const [compteur, setCompteur] = useState(0);

  useEffect(() => {
    const controleur = new AbortController();
    setEtat({ data: null, loading: true, error: null });

    fetch(url, { signal: controleur.signal })
      .then((reponse) => {
        if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
        return reponse.json() as Promise<T>;
      })
      .then((data) => setEtat({ data, loading: false, error: null }))
      .catch((error: unknown) => {
        if ((error as Error).name !== "AbortError") {
          setEtat({ data: null, loading: false, error: error as Error });
        }
      });

    return () => controleur.abort();
  }, [url, compteur]);

  const refetch = useCallback(() => setCompteur((c) => c + 1), []);
  return { ...etat, refetch };
}

from flask import Flask, jsonify, request

app = Flask(__name__)

CHAMPS_REQUIS = ("nom", "email", "message")


@app.post("/api/contact")
def contact():
    donnees = request.get_json(silent=True) or {}
    manquants = [champ for champ in CHAMPS_REQUIS if not donnees.get(champ, "").strip()]
    if manquants:
        return jsonify(
            erreur="Champs manquants : " + ", ".join(manquants)
        ), 400

    email = donnees["email"].strip()
    if "@" not in email or "." not in email:
        return jsonify(erreur="Adresse email invalide."), 400

    # En production : envoi email + persistance en base.
    print(f"Contact de {donnees['nom']} <{email}> : {donnees['message'][:80]}")
    return jsonify(message="Message reçu, nous répondons sous 24 h."), 201


if __name__ == "__main__":
    app.run(debug=True)

