const cible = new Date("2026-06-14T19:00:00");
const affichage = document.querySelector("#decompte");

function maj() {
  const restant = cible - Date.now();
  if (restant <= 0) {
    affichage.textContent = "L'événement a commencé !";
    clearInterval(interval);
    return;
  }
  const jours = Math.floor(restant / 86400000);
  const heures = Math.floor(restant / 3600000) % 24;
  const minutes = Math.floor(restant / 60000) % 60;
  affichage.textContent = `${jours} j ${heures} h ${minutes} min`;
}

