tableau.querySelectorAll("th button").forEach((bouton, index) => {
  bouton.addEventListener("click", () => {
    croissant = index === colonneTriee ? !croissant : true;
    colonneTriee = index;
    const lignes = [...corps.rows];
    lignes.sort((a, b) => {
      const va = a.cells[index].textContent.trim();
      const vb = b.cells[index].textContent.trim();
      const na = Number(va.replace(",", "."));
