async function fetchAvecDelai(url, options = {}, delaiMs = 8000) {
  const controleur = new AbortController();
  const minuteur = setTimeout(() => controleur.abort(), delaiMs);
  try {
    const reponse = await fetch(url, { ...options, signal: controleur.signal });
    if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
    return await reponse.json();
  } finally {
    clearTimeout(minuteur);
  }
}

const donnees = await fetchAvecDelai("/api/produits", {}, 5000);

async function fetchAvecReessais(url, tentatives = 3) {
  for (let essai = 1; essai <= tentatives; essai += 1) {
    try {
      const reponse = await fetch(url);
      if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
      return await reponse.json();
    } catch (erreur) {
      if (essai === tentatives) throw erreur;
      await new Promise((r) => setTimeout(r, essai * 500));
    }
  }
}

