class Panier {
  #articles = [];

  ajouter(reference, prix, quantite = 1) {
    const existant = this.#articles.find((a) => a.reference === reference);
    if (existant) {
      existant.quantite += quantite;
    } else {
      this.#articles.push({ reference, prix, quantite });
    }
    this.sauvegarder();
  }

  retirer(reference) {
    this.#articles = this.#articles.filter((a) => a.reference !== reference);
    this.sauvegarder();
  }

  total() {
    return this.#articles.reduce((somme, a) => somme + a.prix * a.quantite, 0);
  }

  sauvegarder() {
    localStorage.setItem("panier", JSON.stringify(this.#articles));
  }
}

