function creerStore(etatInitial) {
  let etat = etatInitial;
  const abonnes = new Set();
  return {
    lire: () => etat,
    ecrire(nouveau) {
      etat = { ...etat, ...nouveau };
      abonnes.forEach((fn) => fn(etat));
    },
    abonner(fn) {
      abonnes.add(fn);
      fn(etat);
      return () => abonnes.delete(fn);
    },
  };
}

