function tempsRelatif(date) {
  const unitees = [
    ["minute", 60000],
    ["hour", 3600000],
    ["day", 86400000],
  ];
  const difference = date - Date.now();
  for (const [unite, ms] of [...unitees].reverse()) {
    if (Math.abs(difference) >= ms) {
      return new Intl.RelativeTimeFormat("fr", { numeric: "auto" })
        .format(Math.round(difference / ms), unite);
    }
  }
  return "à l'instant";
}

