import { useEffect, useRef } from "react";

type PropsModale = {
  ouverte: boolean;
  titre: string;
  onFermer: () => void;
  children: React.ReactNode;
};

export function Modale({ ouverte, titre, onFermer, children }: PropsModale) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ouverte) return;
    const esc = (e: KeyboardEvent) => e.key === "Escape" && onFermer();
    document.addEventListener("keydown", esc);
    ref.current?.focus();
    return () => document.removeEventListener("keydown", esc);
  }, [ouverte, onFermer]);

  if (!ouverte) return null;
  return (
    <div className="superposition" role="dialog" aria-modal="true" aria-label={titre}
         ref={ref} tabIndex={-1}>
      <div className="modale">
        <h2>{titre}</h2>
        {children}
        <button type="button" onClick={onFermer}>Fermer</button>
      </div>
    </div>
  );
}

