type Tache = { id: number; texte: string; faite: boolean };

export function ListeTaches() {
  const [taches, setTaches] = useState<Tache[]>([]);
  const [texte, setTexte] = useState("");

  function ajouter() {
    const propre = texte.trim();
    if (!propre) return;
    setTaches((precedentes) => [
      ...precedentes,
      { id: Date.now(), texte: propre, faite: false },
    ]);
    setTexte("");
  }

  function basculer(id: number) {
    setTaches((precedentes) =>
      precedentes.map((t) => (t.id === id ? { ...t, faite: !t.faite } : t)));
  }

  return (
    <section>
      <form onSubmit={(e) => { e.preventDefault(); ajouter(); }}>
        <input value={texte} onChange={(e) => setTexte(e.target.value)} />
        <button type="submit">Ajouter</button>
      </form>
      <ul>
        {taches.map((t) => (
          <li key={t.id} className={t.faite ? "faite" : undefined}>
            <label>
              <input type="checkbox" checked={t.faite} onChange={() => basculer(t.id)} />
              {t.texte}
            </label>
          </li>
        ))}
      </ul>
    </section>
  );
}

type PropsPagination = {
  page: number;
  pagesTotal: number;
  onChange: (page: number) => void;
};

export function Pagination({ page, pagesTotal, onChange }: PropsPagination) {
  const numeros = Array.from({ length: pagesTotal }, (_, i) => i + 1)
    .filter((n) => Math.abs(n - page) <= 2 || n === 1 || n === pagesTotal);

  return (
    <nav aria-label="Pagination">
      <button type="button" disabled={page === 1} onClick={() => onChange(page - 1)}>
        Précédent
      </button>
      {numeros.map((n) => (
        <button key={n} type="button" aria-current={n === page ? "page" : undefined}
                onClick={() => onChange(n)}>
          {n}
        </button>
      ))}
      <button type="button" disabled={page === pagesTotal} onClick={() => onChange(page + 1)}>
        Suivant
      </button>
    </nav>
  );
}

import { useEffect, useState } from "react";

type Etat<T> = { donnees: T | null; charge: boolean; erreur: string | null };

export function useFetch<T>(url: string): Etat<T> {
  const [etat, setEtat] = useState<Etat<T>>({ donnees: null, charge: true, erreur: null });

  useEffect(() => {
    const controleur = new AbortController();
    setEtat({ donnees: null, charge: true, erreur: null });
    fetch(url, { signal: controleur.signal })
      .then((reponse) => {
        if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
        return reponse.json() as Promise<T>;
      })
      .then((donnees) => setEtat({ donnees, charge: false, erreur: null }))
      .catch((e: unknown) => {
        if ((e as Error).name !== "AbortError") {
          setEtat({ donnees: null, charge: false, erreur: String((e as Error).message) });
        }
      });
    return () => controleur.abort();
  }, [url]);

  return etat;
}

import { useEffect, useState } from "react";

export function useDebounce<T>(valeur: T, delaiMs = 300): T {
  const [differee, setDifferee] = useState(valeur);
  useEffect(() => {
    const minuteur = setTimeout(() => setDifferee(valeur), delaiMs);
    return () => clearTimeout(minuteur);
  }, [valeur, delaiMs]);
  return differee;
}

import { useEffect, useState } from "react";

export function useLocalStorage<T>(cle: string, defaut: T) {
  const [valeur, setValeur] = useState<T>(() => {
    try {
      const brut = localStorage.getItem(cle);
      return brut ? (JSON.parse(brut) as T) : defaut;
    } catch {
      return defaut;
    }
  });

  useEffect(() => {
    localStorage.setItem(cle, JSON.stringify(valeur));
  }, [cle, valeur]);

  return [valeur, setValeur] as const;
}

import { useEffect, useState } from "react";

export function useMediaQuery(requete: string): boolean {
  const [correspond, setCorrespond] = useState(
    () => typeof window !== "undefined" && window.matchMedia(requete).matches);

  useEffect(() => {
    const liste = window.matchMedia(requete);
    const ecouter = (e: MediaQueryListEvent) => setCorrespond(e.matches);
    liste.addEventListener("change", ecouter);
    setCorrespond(liste.matches);
    return () => liste.removeEventListener("change", ecouter);
  }, [requete]);

  return correspond;
}

import { useEffect, useRef } from "react";

export function usePrevious<T>(valeur: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  useEffect(() => {
    ref.current = valeur;
  }, [valeur]);
  return ref.current;
}

import { useEffect, type RefObject } from "react";

export function useClickOutside(ref: RefObject<HTMLElement | null>, callback: () => void) {
  useEffect(() => {
    function ecouter(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) callback();
    }
    document.addEventListener("mousedown", ecouter);
    return () => document.removeEventListener("mousedown", ecouter);
  }, [ref, callback]);
}

import { useEffect, useRef } from "react";

export function useInterval(callback: () => void, delaiMs: number | null) {
  const ref = useRef(callback);
  useEffect(() => { ref.current = callback; }, [callback]);
  useEffect(() => {
    if (delaiMs === null) return;
    const id = setInterval(() => ref.current(), delaiMs);
    return () => clearInterval(id);
  }, [delaiMs]);
}

import { useEffect, useState } from "react";

type TailleFenetre = { largeur: number; hauteur: number };

export function useWindowSize(): TailleFenetre {
  const [taille, setTaille] = useState<TailleFenetre>({
    largeur: typeof window === "undefined" ? 0 : window.innerWidth,
    hauteur: typeof window === "undefined" ? 0 : window.innerHeight,
  });

  useEffect(() => {
    const mesurer = () =>
      setTaille({ largeur: window.innerWidth, hauteur: window.innerHeight });
    window.addEventListener("resize", mesurer);
    return () => window.removeEventListener("resize", mesurer);
  }, []);

  return taille;
}

