type EtatPanier = { articles: { ref: string; qte: number }[] };
type Action =
  | { type: "ajouter"; ref: string }
  | { type: "retirer"; ref: string }
  | { type: "vider" };

function reducer(etat: EtatPanier, action: Action): EtatPanier {
  switch (action.type) {
    case "ajouter": {
      const existe = etat.articles.find((a) => a.ref === action.ref);
      return {
        articles: existe
          ? etat.articles.map((a) => (a.ref === action.ref ? { ...a, qte: a.qte + 1 } : a))
          : [...etat.articles, { ref: action.ref, qte: 1 }],
      };
    }
    case "retirer":
      return { articles: etat.articles.filter((a) => a.ref !== action.ref) };
    case "vider":
      return { articles: [] };
  }
}

