from pathlib import Path

from flask import Flask, abort, request, send_from_directory

app = Flask(__name__)
DOSSIER = Path(app.instance_path) / "televersements"
DOSSIER.mkdir(parents=True, exist_ok=True)
EXTENSIONS_OK = {".pdf", ".png", ".jpg"}
TAILLE_MAX = 5 * 1024 * 1024


@app.post("/api/televerser")
def televerser():
    fichier = request.files.get("fichier")
    if not fichier or not fichier.filename:
        abort(400, description="Fichier manquant")
    chemin = Path(fichier.filename)
    if chemin.suffix.lower() not in EXTENSIONS_OK:
        abort(415, description="Type de fichier non autorisé")
    fichier.seek(0, 2)
    if fichier.tell() > TAILLE_MAX:
        abort(413, description="Fichier trop volumineux (5 Mo max)")
    fichier.seek(0)
    destination = DOSSIER / chemin.name
    fichier.save(destination)
    return {"fichier": chemin.name, "taille": destination.stat().st_size}, 201


@app.get("/fichiers/<nom>")
def telecharger(nom):
    return send_from_directory(DOSSIER, nom)

