from flask import Blueprint, jsonify, request

bp = Blueprint("avis", __name__, url_prefix="/api/avis")
AVIS = []


@bp.get("")
def lister():
    produit = request.args.get("produit")
    retenus = [a for a in AVIS if not produit or a["produit"] == produit]
    return jsonify(avis=retenus)


@bp.post("")
def creer():
    donnees = request.get_json(silent=True) or {}
    texte = donnees.get("texte", "").strip()
    note = donnees.get("note")
    if len(texte) < 30 or note not in (1, 2, 3, 4, 5):
        return jsonify(erreur="texte >= 30 caractères et note 1-5 requis"), 400
    avis = {"produit": donnees.get("produit", ""), "texte": texte, "note": note}
    AVIS.append(avis)
    return jsonify(avis), 201

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI(title="API réservations")


class Reservation(BaseModel):
    nom: str = Field(min_length=2, max_length=80)
    couverts: int = Field(ge=1, le=12)
    creneau: str


RESERVATIONS: dict[int, Reservation] = {}
_compteur = 0


@app.post("/reservations", status_code=201)
def creer(reservation: Reservation):
    global _compteur
    _compteur += 1
    RESERVATIONS[_compteur] = reservation
    return {"id": _compteur, **reservation.model_dump()}


@app.get("/reservations/{identifiant}")
def lire(identifiant: int):
    if identifiant not in RESERVATIONS:
        raise HTTPException(status_code=404, detail="Réservation inconnue")
    return RESERVATIONS[identifiant]


@app.delete("/reservations/{identifiant}", status_code=204)
def annuler(identifiant: int):
    RESERVATIONS.pop(identifiant, None)

