#!/usr/bin/env python3
"""Range les fichiers du dossier courant dans des sous-dossiers par type."""

import shutil
from pathlib import Path

DOSSIERS = {
    "images": {".jpg", ".jpeg", ".png", ".webp"},
    "documents": {".pdf", ".docx", ".txt"},
    "tableurs": {".csv", ".xlsx"},
    "archives": {".zip", ".tar.gz"},
}


def categorie(extension: str) -> str:
    for nom, extensions in DOSSIERS.items():
        if extension.lower() in extensions:
            return nom
    return "divers"


def ranger(dossier: Path) -> None:
    for fichier in dossier.iterdir():
        if not fichier.is_file():
            continue
        cible = dossier / categorie(fichier.suffix)
        cible.mkdir(exist_ok=True)
        shutil.move(str(fichier), cible / fichier.name)
        print(f"{fichier.name} -> {cible.name}/")


if __name__ == "__main__":
    ranger(Path.cwd())

import re
from html.parser import HTMLParser
from urllib.request import Request, urlopen


class ChercheurLiens(HTMLParser):
    def __init__(self):
        super().__init__()
        self.liens: list[str] = []

    def handle_starttag(self, balise, attributs):
        if balise == "a":
            for nom, valeur in attributs:
                if nom == "href" and valeur and valeur.startswith("http"):
                    self.liens.append(valeur)


def verifier(page_url: str) -> None:
    requete = Request(page_url, headers={"User-Agent": "verificateur-liens/1.0"})
    with urlopen(requete, timeout=10) as reponse:
        chercheur = ChercheurLiens()
        chercheur.feed(reponse.read().decode("utf-8", errors="replace"))
    for lien in sorted(set(chercheur.liens)):
        try:
            with urlopen(Request(lien, headers={"User-Agent": "verificateur-liens/1.0"}),
                         timeout=10) as cible:
                etat = "OK" if cible.status == 200 else f"HTTP {cible.status}"
        except Exception as exc:
            etat = f"ERREUR ({exc.__class__.__name__})"
        print(f"{etat:<20}{lien}")


if __name__ == "__main__":
    verifier("https://exemple.fr")

import secrets
import string

ALPHABETS = (
    string.ascii_lowercase,
    string.ascii_uppercase,
    string.digits,
    "!@#$%&*?",
)


def mot_de_passe(longueur: int = 16) -> str:
    if longueur < len(ALPHABETS) + 2:
        raise ValueError("longueur trop petite")
    caractères = [secrets.choice(a) for a in ALPHABETS]
    reste = longueur - len(caractères)
    tous = "".join(ALPHABETS)
    caractères += [secrets.choice(tous) for _ in range(reste)]
    secrets.SystemRandom().shuffle(caractères)
    return "".join(caractères)


if __name__ == "__main__":
    for _ in range(3):
        print(mot_de_passe())

from html.parser import HTMLParser
from urllib.request import Request, urlopen


class ExtracteurTitres(HTMLParser):
    def __init__(self):
        super().__init__()
        self.dans_h2 = False
        self.titres: list[str] = []

    def handle_starttag(self, balise, attributs):
        if balise == "h2":
            self.dans_h2 = True

    def handle_endtag(self, balise):
        if balise == "h2":
            self.dans_h2 = False

    def handle_data(self, donnees):
        if self.dans_h2 and donnees.strip():
            self.titres.append(" ".join(donnees.split()))


def titres_de(url: str) -> list[str]:
    requete = Request(url, headers={"User-Agent": "extracteur/1.0"})
    with urlopen(requete, timeout=10) as reponse:
        extracteur = ExtracteurTitres()
        extracteur.feed(reponse.read().decode("utf-8", errors="replace"))
    return extracteur.titres


for titre in titres_de("https://exemple.fr/blog"):
    print("-", titre)

