def pages(elements: list, taille: int):
    """Générateur qui rend les éléments page par page."""
    for debut in range(0, len(elements), taille):
        yield elements[debut:debut + taille]


articles = list(range(1, 26))
for numero, page in enumerate(pages(articles, 10), start=1):
    print(f"Page {numero} : {page[0]}..{page[-1]} ({len(page)} éléments)")

CREATE TABLE auteurs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nom VARCHAR(80) NOT NULL,
  email VARCHAR(120) NOT NULL UNIQUE
);

CREATE TABLE articles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  auteur_id INTEGER NOT NULL REFERENCES auteurs(id),
  titre VARCHAR(160) NOT NULL,
  slug VARCHAR(180) NOT NULL UNIQUE,
  contenu TEXT NOT NULL,
  publie_le DATE,
  cree_le TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_articles_auteur ON articles(auteur_id);
CREATE INDEX idx_articles_publie ON articles(publie_le);

CREATE TABLE livres (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  isbn VARCHAR(20) NOT NULL UNIQUE,
  titre VARCHAR(200) NOT NULL,
  auteur VARCHAR(120) NOT NULL,
  annee INTEGER CHECK (annee BETWEEN 1450 AND 2100)
);

CREATE TABLE emprunts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  livre_id INTEGER NOT NULL REFERENCES livres(id),
  lecteur VARCHAR(80) NOT NULL,
  emprunte_le DATE NOT NULL,
  rendu_le DATE,
  CHECK (rendu_le IS NULL OR rendu_le >= emprunte_le)
);

CREATE INDEX idx_emprunts_livre ON emprunts(livre_id);

CREATE TABLE services (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nom VARCHAR(60) NOT NULL UNIQUE
);

CREATE TABLE employes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nom VARCHAR(80) NOT NULL,
  service_id INTEGER NOT NULL REFERENCES services(id),
  salaire DECIMAL(9,2) NOT NULL CHECK (salaire > 0),
  embauche_le DATE NOT NULL
);

CREATE INDEX idx_employes_service ON employes(service_id);

CREATE TABLE chambres (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  numero VARCHAR(5) NOT NULL UNIQUE,
  type VARCHAR(20) NOT NULL CHECK (type IN ('simple', 'double', 'suite')),
  prix_nuit DECIMAL(7,2) NOT NULL
);

CREATE TABLE reservations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  chambre_id INTEGER NOT NULL REFERENCES chambres(id),
  arrivee DATE NOT NULL,
  depart DATE NOT NULL,
  client VARCHAR(80) NOT NULL,
  CHECK (depart > arrivee)
);

CREATE INDEX idx_res_chambre_dates ON reservations(chambre_id, arrivee, depart);

CREATE TABLE clients (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  raison_sociale VARCHAR(120) NOT NULL,
  siret VARCHAR(14) UNIQUE
);

CREATE TABLE factures (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  client_id INTEGER NOT NULL REFERENCES clients(id),
  numero VARCHAR(12) NOT NULL UNIQUE,
  total_ht DECIMAL(10,2) NOT NULL,
  tva DECIMAL(4,3) NOT NULL DEFAULT 0.200,
  emise_le DATE NOT NULL
);

CREATE INDEX idx_factures_client ON factures(client_id, emise_le);

CREATE TABLE categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  nom VARCHAR(60) NOT NULL UNIQUE
);

CREATE TABLE produits (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  categorie_id INTEGER NOT NULL REFERENCES categories(id),
  reference VARCHAR(12) NOT NULL UNIQUE,
  nom VARCHAR(120) NOT NULL,
  prix_ht DECIMAL(8,2) NOT NULL CHECK (prix_ht >= 0),
  stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0)
);

CREATE TABLE commandes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  client VARCHAR(120) NOT NULL,
  email VARCHAR(120) NOT NULL,
  passee_le TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  statut VARCHAR(15) NOT NULL DEFAULT 'en_attente'
      CHECK (statut IN ('en_attente', 'payee', 'expediee', 'annulee'))
);

CREATE TABLE lignes_commande (
  commande_id INTEGER NOT NULL REFERENCES commandes(id),
  produit_id INTEGER NOT NULL REFERENCES produits(id),
  quantite INTEGER NOT NULL CHECK (quantite > 0),
  prix_unitaire DECIMAL(8,2) NOT NULL,
  PRIMARY KEY (commande_id, produit_id)
);

CREATE INDEX idx_produits_categorie ON produits(categorie_id);
CREATE INDEX idx_commandes_statut ON commandes(statut, passee_le);

