const ecran = document.querySelector("#session-ecran");
const DUREE = 50 * 60;
let restant = DUREE;
let minuteur = null;

function afficher() {
  const m = String(Math.floor(restant / 60)).padStart(2, "0");
  const s = String(restant % 60).padStart(2, "0");
  ecran.textContent = `${m}:${s}`;
}

document.querySelector("#session-demarrer").addEventListener("click", () => {
  if (minuteur) return;
  minuteur = setInterval(() => {
    restant -= 1;
    afficher();
    if (restant <= 0) {
      clearInterval(minuteur);
      minuteur = null;
      ecran.textContent = "Session terminée, faites une pause.";
    }
  }, 1000);
});
document.querySelector("#session-reset").addEventListener("click", () => {
  clearInterval(minuteur);
  minuteur = null;
  restant = DUREE;
  afficher();
});
afficher();

