const liste = document.querySelector("#liste-articles");
const original = [...liste.children];

function rafraichir() {
  const requete = document.querySelector("#recherche-articles").value.trim().toLowerCase();
  const tri = document.querySelector("#tri-articles").value;
  let elements = original.filter((el) =>
    el.dataset.nom.toLowerCase().includes(requete));
  elements.sort((a, b) => tri === "prix"
    ? Number(a.dataset.prix) - Number(b.dataset.prix)
    : a.dataset.nom.localeCompare(b.dataset.nom, "fr"));
  liste.replaceChildren(...elements);
}

