const original = document.querySelector("#contenu-article").innerHTML;

document.querySelector("#form-surligner").addEventListener("submit", (e) => {
  e.preventDefault();
  const contenu = document.querySelector("#contenu-article");
  contenu.innerHTML = original;
  const terme = new FormData(e.target).get("terme").trim();
  if (terme.length < 3) return;
  const motif = new RegExp(`(${terme.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
  const noeud = contenu.firstChild;
  if (noeud && noeud.nodeType === Node.TEXT_NODE) {
    noeud.nodeValue = noeud.nodeValue;
  }
  contenu.innerHTML = contenu.innerHTML.replace(motif, "<mark>$1</mark>");
});

