const chiffre = document.querySelector("#chiffre-cle");
const cible = Number(chiffre.dataset.cible);
const DUREE = 1200;

function animer(debut) {
  const progression = Math.min((performance.now() - debut) / DUREE, 1);
  const aise = 1 - Math.pow(1 - progression, 3);
  chiffre.textContent = Math.round(cible * aise).toLocaleString("fr-FR");
  if (progression < 1) requestAnimationFrame(() => animer(debut));
}

const observateur = new IntersectionObserver((entrees) => {
  if (entrees[0].isIntersecting) {
    requestAnimationFrame(animer);
    observateur.disconnect();
  }
});
observateur.observe(chiffre);

function lireJSON(nomId, defaut = null) {
  const balise = document.getElementById(nomId);
  if (!balise) return defaut;
  try {
    return JSON.parse(balise.textContent);
  } catch {
    console.warn("JSON invalide dans", nomId);
    return defaut;
  }
}

const config = lireJSON("config-page", { theme: "clair" });

function tailleLisible(octets) {
  if (octets < 1024) return `${octets} o`;
  if (octets < 1024 * 1024) return `${(octets / 1024).toFixed(1)} Ko`;
