import { useCallback, useState } from "react";

export function useObjetPersiste<T extends object>(cle: string, defaut: T) {
  const [valeur, setValeur] = useState<T>(() => {
    try {
      const brut = localStorage.getItem(cle);
      return brut ? { ...defaut, ...(JSON.parse(brut) as T) } : defaut;
    } catch {
      return defaut;
    }
  });

  const maj = useCallback(
    (fragment: Partial<T>) => {
      setValeur((precedente) => {
        const suivante = { ...precedente, ...fragment };
        localStorage.setItem(cle, JSON.stringify(suivante));
        return suivante;
      });
    },
    [cle]);

  return { valeur, maj } as const;
}

import { useEffect, useState } from "react";

export function useCompteurAnime(cible: number, dureeMs = 1000): number {
  const [valeur, setValeur] = useState(0);

  useEffect(() => {
    let id: number;
    const debut = performance.now();
    const pas = (maintenant: number) => {
      const progression = Math.min((maintenant - debut) / dureeMs, 1);
      setValeur(Math.round(cible * (1 - Math.pow(1 - progression, 3))));
      if (progression < 1) id = requestAnimationFrame(pas);
    };
    id = requestAnimationFrame(pas);
    return () => cancelAnimationFrame(id);
  }, [cible, dureeMs]);

  return valeur;
}

