const cache = new Map<string, unknown>();

export function useApiCache<T>() {
  const [etats, setEtats] = useState<Record<string, T | "charge" | null>>({});

  const charger = useCallback(async (url: string) => {
    if (cache.has(url)) {
      setEtats((e) => ({ ...e, [url]: cache.get(url) as T }));
      return;
    }
    setEtats((e) => ({ ...e, [url]: "charge" }));
    const reponse = await fetch(url);
    if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
    const donnees = (await reponse.json()) as T;
    cache.set(url, donnees);
    setEtats((e) => ({ ...e, [url]: donnees }));
  }, []);

  return { etats, charger };
}

