import re
from collections import Counter
from pathlib import Path

MOTIF = re.compile(r'^(?P<ip>\S+) .* "(?P<verbe>\w+) (?P<route>\S+)" (?P<statut>\d{3})')


def analyser(chemin: Path) -> dict[str, int]:
    routes: Counter = Counter()
    erreurs = 0
    for ligne in chemin.open(encoding="utf-8", errors="replace"):
        correspondance = MOTIF.match(ligne)
        if not correspondance:
            continue
        if correspondance.group("statut").startswith("4"):
            erreurs += 1
        routes[correspondance.group("route")] += 1
    return {"erreurs_4xx": erreurs, "route_top": routes.most_common(1)[0][0]}


