    donnees = request.get_json(silent=True) or {}
    email = donnees.get("email", "").strip().lower()
    if "@" not in email or "." not in email.split("@")[-1]:
        return jsonify(erreur="adresse email invalide"), 400
    if email in LISTE_DIFFUSION:
        return jsonify(message="déjà inscrite ou inscrit"), 200
    LISTE_DIFFUSION.add(email)
    return jsonify(message="inscription confirmée"), 201


@app.delete("/api/newsletter")
def desinscrire():
    donnees = request.get_json(silent=True) or {}
    email = donnees.get("email", "").strip().lower()
    LISTE_DIFFUSION.discard(email)
    return jsonify(message="désinscription enregistrée"), 200

from http.server import BaseHTTPRequestHandler, HTTPServer
import json

PRIX = {"SAC-01": 29.0, "BOU-04": 18.0}


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/prix":
            self.repondre(200, PRIX)
        else:
            self.repondre(404, {"erreur": "route inconnue"})

    def repondre(self, statut: int, corps: dict) -> None:
        payload = json.dumps(corps, ensure_ascii=False).encode("utf-8")
        self.send_response(statut)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)


if __name__ == "__main__":
    serveur = HTTPServer(("127.0.0.1", 8123), Handler)
    print("API de démonstration sur http://127.0.0.1:8123")
    serveur.serve_forever()

