const iban = document.querySelector("#iban");
const retour = document.querySelector("#iban-retour");

iban.addEventListener("input", () => {
  const brut = iban.value.replace(/\s/g, "").toUpperCase();
  iban.value = brut.replace(/(.{4})/g, "$1 ").trim();
  if (brut.length === 0) {
    retour.textContent = "";
  } else if (brut.length < 27) {
    retour.textContent = `Il manque ${27 - brut.length} caractères.`;
  } else {
    retour.textContent = "Format complet (vérification banque à l'enregistrement).";
  }
});

const zone = document.querySelector("#texte-sms");
const estimation = document.querySelector("#estimation-sms");
const PAR_SMS = 160;
const MAX = PAR_SMS * 5;

zone.addEventListener("input", () => {
  if (zone.value.length > MAX) zone.value = zone.value.slice(0, MAX);
  const messages = Math.max(1, Math.ceil(zone.value.length / PAR_SMS));
  estimation.textContent = `${messages} SMS (${zone.value.length}/${MAX} caractères)`;
});

const liste = document.querySelector("#liste-courses");
const form = document.querySelector("#form-course");
let articles = JSON.parse(localStorage.getItem("courses") ?? "[]");

function sauver() {
  localStorage.setItem("courses", JSON.stringify(articles));
  const total = articles.reduce((s, a) => s + a.quantite, 0);
  document.querySelector("#total-courses").textContent =
    `${total} article${total > 1 ? "s" : ""} à acheter`;
}

function rendre() {
  liste.replaceChildren(...articles.map((article) => {
    const item = document.createElement("li");
    const nom = document.createElement("span");
    nom.textContent = `${article.quantite} × ${article.nom}`;
    const plus = document.createElement("button");
    plus.type = "button";
    plus.textContent = "+";
    plus.addEventListener("click", () => {
      article.quantite += 1;
      sauver(); rendre();
    });
    const moins = document.createElement("button");
    moins.type = "button";
    moins.textContent = "−";
    moins.addEventListener("click", () => {
      article.quantite -= 1;
      if (article.quantite <= 0) {
        articles = articles.filter((a) => a !== article);
      }
      sauver(); rendre();
    });
    item.append(moins, nom, plus);
    return item;
  }));
  sauver();
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const nom = new FormData(form).get("nom").trim();
  if (!nom) return;
  const existant = articles.find((a) => a.nom.toLowerCase() === nom.toLowerCase());
  if (existant) existant.quantite += 1;
  else articles.push({ nom, quantite: 1 });
  form.reset();
  rendre();
});
rendre();

