const CLE = "colonnes-visibles";
const visibles = new Set(JSON.parse(localStorage.getItem(CLE) ??
  '["nom","total"]'));

function appliquer() {
  document.querySelectorAll("th[data-colonne], td[data-colonne]").forEach((cellule) => {
    cellule.hidden = !visibles.has(cellule.dataset.colonne);
  });
}

document.querySelectorAll(".basculer-colonne").forEach((caseCoche) => {
  caseCoche.checked = visibles.has(caseCoche.dataset.colonne);
  caseCoche.addEventListener("change", () => {
    caseCoche.checked ? visibles.add(caseCoche.dataset.colonne)
                      : visibles.delete(caseCoche.dataset.colonne);
    localStorage.setItem(CLE, JSON.stringify([...visibles]));
    appliquer();
  });
});
appliquer();

