const HORAIRES = ["09:00", "10:30", "14:00", "15:30", "17:00"];
const conteneur = document.querySelector("#creneaux");
const maintenant = new Date();

HORAIRES.forEach((horaire) => {
  const [h, m] = horaire.split(":").map(Number);
  const passe = new Date();
  passe.setHours(h, m, 0, 0);
  const disabled = passe <= maintenant ? " disabled" : "";

  const label = document.createElement("label");
  label.innerHTML = `<input type="radio" name="creneau" value="${horaire}"${disabled}>
    ${horaire}`;
  conteneur.append(label);
});

conteneur.addEventListener("change", () => {
  const choisi = conteneur.querySelector("input:checked")?.value;
  document.querySelector("#creneau-choisi").textContent =
    choisi ? `Rendez-vous à ${choisi}` : "";
});

const compteur = document.querySelector("#compteur-objectif");
const but = Number(compteur.dataset.but);
let valeur = 0;

function rendre() {
  const pourcent = Math.min(100, Math.round((valeur / but) * 100));
  compteur.querySelector(".barre").style.width = `${pourcent}%`;
  compteur.querySelector(".chiffre").textContent = `${valeur} / ${but}`;
  if (valeur >= but) {
    compteur.querySelector(".message").textContent = "Objectif atteint, bravo !";
  }
}

document.querySelector("#objectif-plus").addEventListener("click", () => {
  valeur = Math.min(but, valeur + 1);
  rendre();
});
rendre();

const zone = document.querySelector("#reponse-chat");

zone.addEventListener("keydown", (evenement) => {
  if (evenement.key === "Enter" && !evenement.shiftKey) {
    evenement.preventDefault();
    const texte = zone.value.trim();
    if (!texte) return;
    fetch("/api/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ texte }),
    }).then(() => {
      zone.value = "";
      zone.style.height = "auto";
    });
  }
});

const liste = document.querySelector("#liste-favoris-tri");
let indexSource = null;

[...liste.children].forEach((item, index) => {
  item.draggable = true;
  item.addEventListener("dragstart", () => (indexSource = index));
  item.addEventListener("dragover", (e) => e.preventDefault());
  item.addEventListener("drop", (e) => {
    e.preventDefault();
    const cible = [...liste.children][indexSource];
    if (cible && cible !== item) {
      item.before(cible);
      localStorage.setItem("ordre-favoris",
        [...liste.children].map((el) => el.dataset.id).join(","));
    }
  });
});

const TAUX = { usd: 1.08, gbp: 0.85, chf: 0.94 };
const montant = document.querySelector("#montant-eur");
const resultats = document.querySelector("#conversions");

function convertir() {
  const euros = parseFloat(montant.value.replace(",", ".")) || 0;
  resultats.innerHTML = Object.entries(TAUX)
    .map(([devise, taux]) =>
      `<li>${(euros * taux).toFixed(2)} ${devise.toUpperCase()}</li>`)
    .join("");
}
montant.addEventListener("input", convertir);
convertir();

const champs = document.querySelectorAll(".champ-signature");
const apercu = document.querySelector("#apercu-signature");
const brut = document.querySelector("#signature-brute");

function composer() {
  const valeurs = [...champs].map((c) => c.value.trim());
  const [nom, fonction, telephone] = valeurs;
  const signature = `<strong>${nom || "Votre nom"}</strong><br>
${fonction || "Fonction"}<br>
<a href="tel:${(telephone || "").replace(/\s/g, "")}">${telephone || "06 00 00 00 00"}</a>`;
  apercu.innerHTML = signature;
  brut.value = signature;
}
champs.forEach((c) => c.addEventListener("input", composer));
composer();

document.querySelector("#copier-signature").addEventListener("click", async () => {
  await navigator.clipboard.writeText(brut.value);
});

const formulaire = document.querySelector("#form-edition");
const instantane = new FormData(formulaire);
const indicateur = document.querySelector("#indicateur-modifs");

function modifie() {
  const courant = new FormData(formulaire);
  return [...instantane.keys()].some((cle) =>
    instantane.get(cle) !== courant.get(cle));
}

formulaire.addEventListener("input", () => {
  const modifs = modifie();
  indicateur.hidden = !modifs;
  window.onbeforeunload = modifs ? () => true : null;
});
formulaire.addEventListener("submit", () => {
  window.onbeforeunload = null;
});

const zone = document.querySelector("#loupe-produit");

zone.addEventListener("pointermove", (e) => {
  const rect = zone.getBoundingClientRect();
  const x = ((e.clientX - rect.left) / rect.width) * 100;
  const y = ((e.clientY - rect.top) / rect.height) * 100;
  zone.style.backgroundPosition = `${x}% ${y}%`;
});

const fin = new Date();
fin.setHours(23, 59, 59, 999);
const affichage = document.querySelector("#offre-restant");

function maj() {
  const restant = fin - Date.now();
  if (restant <= 0) {
    affichage.textContent = "L'offre est terminée.";
    clearInterval(interval);
    return;
  }
  const h = String(Math.floor(restant / 3600000)).padStart(2, "0");
  const m = String(Math.floor(restant / 60000) % 60).padStart(2, "0");
  const s = String(Math.floor(restant / 1000) % 60).padStart(2, "0");
  affichage.textContent = `Fin de l'offre dans ${h}:${m}:${s}`;
}
const interval = setInterval(maj, 1000);
maj();

const liens = [...document.querySelectorAll(".sommaire a")];
const sections = liens.map((lien) =>
  document.querySelector(lien.getAttribute("href")));

const observateur = new IntersectionObserver((entrees) => {
  entrees.forEach((entree) => {
    if (!entree.isIntersecting) return;
    liens.forEach((lien) => {
      lien.removeAttribute("aria-current");
    });
    const index = sections.indexOf(entree.target);
    liens[index]?.setAttribute("aria-current", "true");
  });
}, { rootMargin: "-40% 0px -50% 0px" });

sections.forEach((section) => section && observateur.observe(section));

const carte = document.querySelector("#numero-carte");

carte.addEventListener("blur", () => {
  const chiffres = carte.value.replace(/\D/g, "");
  if (chiffres.length < 4) return;
  carte.value = "•".repeat(chiffres.length - 4) + chiffres.slice(-4);
});
carte.addEventListener("focus", () => {
  carte.value = carte.value.replace(/•/g, "");
});

const SOULI_GRATUIT = 50;
const FRAIS = 4.9;

function majPort() {
  const sousTotal = Number(document.querySelector("#sous-total").dataset.montant);
  const zone = document.querySelector("#frais-port");
  if (sousTotal >= SOULI_GRATUIT) {
    zone.textContent = "Livraison offerte";
    zone.classList.add("gratuit");
  } else {
    const reste = SOULI_GRATUIT - sousTotal;
    zone.textContent =
      `${FRAIS.toLocaleString("fr-FR", { style: "currency", currency: "EUR" })} ` +
      `(encore ${reste.toLocaleString("fr-FR",
        { style: "currency", currency: "EUR" })} pour la livraison offerte)`;
    zone.classList.remove("gratuit");
  }
}
majPort();

const modale = document.querySelector("#modale-focus");
const FOCALISABLES = "a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex='-1'])";

modale.addEventListener("keydown", (e) => {
  if (e.key !== "Tab") return;
  const elements = [...modale.querySelectorAll(FOCALISABLES)];
  const premier = elements[0];
  const dernier = elements[elements.length - 1];
  if (e.shiftKey && document.activeElement === premier) {
    e.preventDefault();
    dernier.focus();
  } else if (!e.shiftKey && document.activeElement === dernier) {
    e.preventDefault();
    premier.focus();
  }
});

const annonceur = document.querySelector("#annonce-panier");

function annoncer(texte) {
  annonceur.textContent = "";
  requestAnimationFrame(() => {
    annonceur.textContent = texte;
  });
}

document.querySelectorAll("[data-ajouter]").forEach((bouton) => {
  bouton.addEventListener("click", () =>
    annoncer(`${bouton.dataset.nom} ajouté au panier`));
});

const bouton = document.querySelector("#menu-bouton");
const menu = document.querySelector("#menu-deroulant");
const items = [...menu.querySelectorAll("a")];

bouton.addEventListener("click", () => {
  const ouvert = bouton.getAttribute("aria-expanded") === "true";
  bouton.setAttribute("aria-expanded", String(!ouvert));
  menu.hidden = ouvert;
  if (!ouvert) items[0].focus();
});

menu.addEventListener("keydown", (e) => {
  const index = items.indexOf(document.activeElement);
  if (e.key === "ArrowDown") {
    e.preventDefault();
    items[(index + 1) % items.length].focus();
  } else if (e.key === "ArrowUp") {
    e.preventDefault();
    items[(index - 1 + items.length) % items.length].focus();
  } else if (e.key === "Escape") {
    menu.hidden = true;
    bouton.setAttribute("aria-expanded", "false");
    bouton.focus();
  }
});

const cible = document.querySelector(".element-defilant");

function defiler() {
  const reduit = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduit) {
    cible.scrollIntoView();
    return;
  }
  cible.scrollIntoView({ behavior: "smooth", block: "center" });
}

document.querySelector("#aller-a-la-section").addEventListener("click", defiler);

const formulaire = document.querySelector("#form-erreurs");

formulaire.addEventListener("submit", (e) => {
  e.preventDefault();
  const erreurs = [];
  formulaire.querySelectorAll("[required]").forEach((champ) => {
    champ.removeAttribute("aria-describedby");
    const message = champ.nextElementSibling;
    if (message?.classList.contains("erreur-champ")) message.remove();
    if (!champ.checkValidity()) {
      const id = `erreur-${champ.name}`;
      const bloc = document.createElement("small");
      bloc.id = id;
      bloc.className = "erreur-champ";
      bloc.textContent = champ.validationMessage;
      champ.after(bloc);
      champ.setAttribute("aria-describedby", id);
      erreurs.push(champ);
    }
  });
  erreurs[0]?.focus();
});

const bouton = document.querySelector("#contraste-eleve");
const CLE = "contraste-eleve";

function appliquer() {
  const actif = localStorage.getItem(CLE) === "1";
  document.documentElement.classList.toggle("contraste-eleve", actif);
  bouton.setAttribute("aria-pressed", String(actif));
  bouton.textContent = actif ? "Contraste normal" : "Contraste élevé";
}

bouton.addEventListener("click", () => {
  const actif = localStorage.getItem(CLE) === "1";
  localStorage.setItem(CLE, actif ? "0" : "1");
  appliquer();
});
appliquer();

const NIVEAUX = { normal: "1", grand: "1.15", tresGrand: "1.3" };
const boutons = document.querySelectorAll("[data-taille-texte]");

function appliquer(niveau) {
  document.documentElement.style.fontSize = `${NIVEAUX[niveau] ?? 1}rem`;
  localStorage.setItem("taille-texte", niveau);
  boutons.forEach((b) =>
    b.setAttribute("aria-pressed", String(b.dataset.tailleTexte === niveau)));
}

boutons.forEach((b) =>
  b.addEventListener("click", () => appliquer(b.dataset.tailleTexte)));
appliquer(localStorage.getItem("taille-texte") ?? "normal");

async function chargerPage(url) {
  const reponse = await fetch(url);
  const page = await reponse.text();
  document.querySelector("#contenu-dynamique").innerHTML = page;
  const titre = document.querySelector("#contenu-dynamique h1");
  titre.tabIndex = -1;
  titre.focus();
  document.title = `${titre.textContent} — Mon site`;
}

document.querySelectorAll("[data-lien-ajax]").forEach((lien) => {
  lien.addEventListener("click", (e) => {
    e.preventDefault();
    chargerPage(lien.getAttribute("href"));
  });
});

const audio = document.querySelector("#audio-cours");
const bouton = document.querySelector("#audio-bouton");

bouton.addEventListener("click", () => {
  if (audio.paused) {
    audio.play();
    bouton.setAttribute("aria-pressed", "true");
    bouton.textContent = "Pause";
  } else {
    audio.pause();
    bouton.setAttribute("aria-pressed", "false");
    bouton.textContent = "Lecture";
  }
});

audio.addEventListener("timeupdate", () => {
  if (!audio.duration) return;
  const pourcent = Math.round((audio.currentTime / audio.duration) * 100);
  document.querySelector("#audio-progression").textContent = `${pourcent} %`;
});

const boutonFermer = document.querySelector("#fermer-panneau");
const panneau = document.querySelector("#panneau-edition");
let arme = false;
let minuteur = null;

boutonFermer.addEventListener("click", () => {
  if (arme) {
    panneau.hidden = true;
    arme = false;
    boutonFermer.textContent = "Fermer";
    clearTimeout(minuteur);
    return;
  }
  arme = true;
  boutonFermer.textContent = "Perdre vos modifications ?";
  minuteur = setTimeout(() => {
    arme = false;
    boutonFermer.textContent = "Fermer";
  }, 3000);
});

