const presence = document.querySelector("#liste-presences");
const boutonMarquer = document.querySelector("#marquer-tous-presents");

["Amine", "Chloé", "Fatou", "Lucas"].forEach((nom) => {
  const item = document.createElement("li");
  const caseCoche = document.createElement("input");
  caseCoche.type = "checkbox";
  caseCoche.id = `presence-${nom.toLowerCase()}`;
  const label = document.createElement("label");
  label.htmlFor = caseCoche.id;
  label.textContent = nom;
  item.append(caseCoche, label);
  presence.append(item);
});

boutonMarquer.addEventListener("click", () => {
  presence.querySelectorAll("input").forEach((c) => (c.checked = true));
  document.querySelector("#compte-presences").textContent =
    `${presence.querySelectorAll("input:checked").length} présents`;
});

const compteur = document.querySelector("#bouteilles");
let total = Number(localStorage.getItem("consignes") ?? 0);
compteur.textContent = total;

document.querySelector("#consigner").addEventListener("click", () => {
  total += 1;
  localStorage.setItem("consignes", String(total));
  compteur.textContent = total;
});
document.querySelector("#reinitialiser").addEventListener("click", () => {
  total = 0;
  localStorage.removeItem("consignes");
  compteur.textContent = "0";
});

const addition = document.querySelector("#montant-addition");
const pourcentages = document.querySelectorAll("[data-pourboire]");
const affichage = document.querySelector("#total-pourboire");

pourcentages.forEach((bouton) => {
  bouton.addEventListener("click", () => {
    const montant = parseFloat(addition.value.replace(",", ".")) || 0;
    const pourboire = montant * Number(bouton.dataset.pourboire) / 100;
    affichage.textContent =
      `Pourboire : ${pourboire.toLocaleString("fr-FR",
        { style: "currency", currency: "EUR" })} — ` +
      `Total : ${(montant + pourboire).toLocaleString("fr-FR",
        { style: "currency", currency: "EUR" })}`;
  });
});

const participants = document.querySelector("#participants-depenses");
const bouton = document.querySelector("#repartir");

bouton.addEventListener("click", () => {
  const noms = participants.value.split(",").map((n) => n.trim()).filter(Boolean);
  const total = parseFloat(document.querySelector("#total-depenses").value.replace(",", ".")) || 0;
  if (!noms.length || total <= 0) return;
  const part = total / noms.length;
  document.querySelector("#repartition").innerHTML = noms
    .map((nom) => `<li>${nom} : ${part.toLocaleString("fr-FR",
      { style: "currency", currency: "EUR" })}</li>`)
    .join("");
});

const boutonEnvoyer = document.querySelector("#envoyer-definitif");
let pret = false;

boutonEnvoyer.addEventListener("click", () => {
  if (pret) return;
  let secondes = 3;
  boutonEnvoyer.disabled = true;
  boutonEnvoyer.textContent = `Envoi dans ${secondes}…`;
  const interval = setInterval(() => {
    secondes -= 1;
    if (secondes > 0) {
      boutonEnvoyer.textContent = `Envoi dans ${secondes}…`;
      return;
    }
    clearInterval(interval);
    boutonEnvoyer.disabled = false;
    boutonEnvoyer.textContent = "Confirmer l'envoi";
    pret = true;
    setTimeout(() => (pret = false), 4000);
  }, 1000);
});

