import { useEffect, useRef } from "react";

export function RechercheRaccourci() {
  const ref = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const ecouter = (e: KeyboardEvent) => {
      if (e.key === "/" && document.activeElement !== ref.current) {
        e.preventDefault();
        ref.current?.focus();
      }
    };
    document.addEventListener("keydown", ecouter);
    return () => document.removeEventListener("keydown", ecouter);
  }, []);

  return (
    <label>
      Rechercher{" "}
      <kbd aria-hidden="true">/</kbd>
      <input ref={ref} type="search" placeholder="Rechercher…" />
    </label>
  );
}

