import { useEffect, useState } from "react";

export function CompteAReboursOffre({ finISO }: { finISO: string }) {
  const [libelle, setLibelle] = useState("");

  useEffect(() => {
    const fin = new Date(finISO).getTime();
    const interval = setInterval(() => {
      const secondes = Math.max(0, Math.round((fin - Date.now()) / 1000));
      const h = Math.floor(secondes / 3600);
      const m = Math.floor((secondes % 3600) / 60);
      const s = secondes % 60;
      setLibelle(`${h}h ${String(m).padStart(2, "0")}m ${String(s).padStart(2, "0")}s`);
    }, 1000);
    return () => clearInterval(interval);
  }, [finISO]);

  return <p className="compte-a-rebours">{libelle}</p>;
}

