type Creneau = { debut: string; fin: string };

export function creneauValide(creneau: Creneau): string | null {
  const [h1, m1] = creneau.debut.split(":").map(Number);
  const [h2, m2] = creneau.fin.split(":").map(Number);
  const debut = h1 * 60 + m1;
  const fin = h2 * 60 + m2;
  if (fin <= debut) return "L'heure de fin doit suivre l'heure de début.";
  if (fin - debut < 30) return "Un créneau dure au moins 30 minutes.";
  if (fin - debut > 240) return "Un créneau dure au plus 4 heures.";
  return null;
}

