export function pageVoisines(courante: number, total: number, rayon = 2): number[] {
  const debut = Math.max(1, courante - rayon);
  const fin = Math.min(total, courante + rayon);
  const pages = [];
  for (let n = debut; n <= fin; n += 1) pages.push(n);
  if (debut > 1) pages.unshift(1);
  if (fin < total) pages.push(total);
  return [...new Set(pages)].sort((a, b) => a - b);
}

