from pathlib import Path

MOTIF_SLUG = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")

def verifier_slugs(dossier: Path) -> list[str]:
    problemes = []
    for chemin in sorted(dossier.glob("*.html")):
        slug = chemin.stem
        if not MOTIF_SLUG.match(slug):
            problemes.append(f"{slug} : caractères non conformes")
    return problemes

