from pathlib import Path

SEUIL = 5 * 1024 * 1024  # 5 Mo

def scanner(dossier: Path) -> list[tuple[int, Path]]:
    resultats = []
    for chemin in dossier.rglob("*"):
        if chemin.is_file():
            taille = chemin.stat().st_size
            if taille > SEUIL:
                resultats.append((taille, chemin))
    return sorted(resultats, reverse=True)

