export function versionPlusRecente(a: string, b: string): string {
  const [ma, ma2, ma3] = a.split(".").map(Number);
  const [mb, mb2, mb3] = b.split(".").map(Number);
  if (ma !== mb) return ma > mb ? a : b;
  if (ma2 !== mb2) return ma2 > mb2 ? a : b;
  return ma3 >= mb3 ? a : b;
}

