export function capitaliser(texte: string): string {
  return texte.charAt(0).toUpperCase() + texte.slice(1);
}

console.log(capitaliser("bonjour")); // Bonjour

export function somme(valeurs: number[]): number {
  return valeurs.reduce((a, b) => a + b, 0);
}

console.log(somme([1, 2, 3])); // 6

export function estVide(valeur: string | null | undefined): boolean {
  return (valeur ?? "").trim().length === 0;
}

console.log(estVide("   ")); // true

export function premiereValeur<T>(objet: Record<string, T>): T | undefined {
  return Object.values(objet)[0];
}

export function compterMots(texte: string): number {
  return texte.trim().split(/\s+/).filter(Boolean).length;
}

console.log(compterMots("Un essai rapide")); // 3

export function arrondi2(valeur: number): number {
  return Math.round(valeur * 100) / 100;
}

console.log(arrondi2(19.999)); // 20

export function uniquesPar<T>(elements: T[], cle: (e: T) => string): T[] {
  const vus = new Set<string>();
  return elements.filter((e) => {
    const k = cle(e);
    if (vus.has(k)) return false;
    vus.add(k);
    return true;
  });
}

export function basculer(valeur: boolean): boolean {
  return !valeur;
}

export function intervalle(debut: number, fin: number): number[] {
  const resultat: number[] = [];
  for (let n = debut; n <= fin; n += 1) resultat.push(n);
  return resultat;
}

console.log(intervalle(3, 6)); // [3, 4, 5, 6]

export function ouiNon(valeur: boolean): string {
  return valeur ? "Oui" : "Non";
}

from pathlib import Path

def chemin_sous(dossier: str, *parts: str) -> Path:
    return Path(dossier).joinpath(*parts)


print(chemin_sous("site", "pages", "contact.html"))

def mots_uniques(texte: str) -> int:
    return len(set(texte.lower().split()))


print(mots_uniques("Le chat dort le chat rêve"))  # 5

def remise(montant: float, taux: float, plafond: float) -> float:
    reduction = min(montant * taux, plafond)
    return round(montant - reduction, 2)


print(remise(500, 0.2, 60))  # 440.0

def lire_entier(message: str, defaut: int) -> int:
    brut = input(f"{message} [{defaut}] : ").strip()
    return int(brut) if brut.isdigit() else defaut

def enumeration(elements: list[str]) -> str:
    if len(elements) <= 1:
        return " et ".join(elements)
    return ", ".join(elements[:-1]) + " et " + elements[-1]


print(enumeration(["Léa", "Karim", "Inès"]))

def inverser(dictionnaire: dict) -> dict:
    return {v: k for k, v in dictionnaire.items()}


print(inverser({"fr": "Bonjour"}))  # {'Bonjour': 'fr'}

def total_centimes(prix: list[float]) -> int:
    return round(sum(round(p * 100) for p in prix))


print(total_centimes([29.9, 19.1]))  # 4900
